# e3f 検算スクリプト：全問「問題 → 計算した答え」を出し、正解の選択肢と突き合わせる。
# 使い方: python3 e3f.verify.py   （out/e3f/*.json を読む）
import json, glob, os, sys

import re
def fmtv(fmt, v):
    if fmt == 'g': return f"{v}g"
    if fmt == 'kg':
        assert v % 1000 == 0; return f"{v//1000}kg"
    if fmt == 'kgg':
        k, g = divmod(v, 1000)
        return ' '.join(([f"{k}kg"] if k else []) + ([f"{g}g"] if g else []))
    if fmt == 'kgo': return f"{v}kg"
    if fmt == 't':
        assert v % 1000 == 0; return f"{v//1000}t"
    if fmt == 'tkg':
        t, k = divmod(v, 1000)
        return ' '.join(([f"{t}t"] if t else []) + ([f"{k}kg"] if k else []))
    return fmt.format(v)
def parse(kind, text):
    if kind == 'w':
        return sum(int(n) * {'kg': 1000, 'g': 1}[u] for n, u in re.findall(r'(\d+)(kg|g)', text))
    if kind == 'k':
        return sum(int(n) * {'t': 1000, 'kg': 1}[u] for n, u in re.findall(r'(\d+)(t|kg)', text))
    return int(re.match(r'\d+', text).group())

