HERE = os.path.dirname(os.path.abspath(__file__))
items = {}
for f in sorted(glob.glob(os.path.join(HERE, 'e3f', '*.json'))):
    for it in json.load(open(f)): items[it['id']] = it
bad = 0
for r in RECS:
    it = items[r['id']]; cs = it['c']
    ks = [i for i, c in enumerate(cs) if c.get('k') == 1]
    ok = ks == [r['correct']]
    if r['type'] == 'v':
        vals = [eval(x) for x in r['exprs']]
        # exprs[0] が 正解、あとは まちがい。選択肢は 入れかえて いるので 文字から 突き合わせる
        texts = [fmtv(r['fmt'], v) for v in vals]
        correct_text = texts[0]
        ok = ok and cs[ks[0]]['t'] == correct_text and sorted(c['t'] for c in cs) == sorted(texts)
        ok = ok and parse(r['kind'], correct_text) == vals[0]
        ok = ok and all(parse(r['kind'], t) != vals[0] for t in texts[1:])
        print(('OK ' if ok else 'NG ') + it['id'], it['q'][:46], '→', correct_text)
    else:
        tr = [bool(eval(x)) for x in r['exprs']]
        ok = ok and sum(tr) == 1 and r['texts'][tr.index(True)] == cs[ks[0]]['t']
        ok = ok and sorted(c['t'] for c in cs) == sorted(r['texts'])
        print(('OK ' if ok else 'NG ') + it['id'], it['q'][:46], '→', cs[ks[0]]['t'] if ks else '?')
    if not ok: bad += 1
print('問題数', len(RECS), ' NG', bad)
sys.exit(1 if bad else 0)
